/* Redesign chrome: header, sidebar, and Tweaks */
.header {
  min-height: 64px;
  padding: 0 24px;
  background: color-mix(in srgb, var(--bg-primary) 92%, var(--bg-secondary));
  border-bottom: 1px solid var(--border);
  gap: 18px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
}
.brand-mark,
.header h1.brand-mark {
  margin: 0;
  font-family: var(--font-display);
  font-size: 20px;
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0;
  color: var(--accent);
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.pill {
  display: inline-flex;
  align-items: center;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text-muted);
  background: var(--bg-card);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.header-mid {
  flex: 1;
  justify-content: center;
  min-width: 0;
  gap: 10px;
}
.header-right {
  justify-content: flex-end;
  gap: 8px;
  min-width: 190px;
}
.chip {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  white-space: nowrap;
}
.chip .label,
.header-info .label {
  color: var(--text-muted);
}
.profile-compact-btn {
  min-height: 34px;
  padding: 4px 10px 4px 5px;
  border-radius: var(--radius-sm);
  background: var(--bg-card);
}
.range-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0;
  padding: 2px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
}
.range-toggle-btn {
  border: 0;
  border-radius: calc(var(--radius-sm) - 2px);
  background: transparent;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  padding: 6px 11px;
}
.range-toggle-btn.active {
  background: var(--accent);
  color: var(--on-accent);
  border-color: transparent;
}
.header-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-card);
  color: var(--text-secondary);
}
.header-icon-btn:hover {
  color: var(--text-primary);
  border-color: var(--accent);
  background: var(--bg-hover);
}
.header-share-btn {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--bg-card));
}
.header-share-btn:hover {
  color: var(--on-accent);
  background: var(--accent);
  border-color: var(--accent);
}
.donate-btn,
.donate-btn:hover {
  width: auto;
  height: 36px;
  padding: 0 14px;
  border: 0;
  background: var(--donate-accent);
  color: var(--on-donate-accent);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  gap: 4px;
  white-space: nowrap;
}
.donate-split,
.donate-split:hover {
  display: inline-grid;
  grid-template-columns: 1fr 1fr;
  min-width: 132px;
  padding: 0;
  overflow: hidden;
  background: linear-gradient(100deg, #f7931a 0%, #f7931a 38%, #c98358 49%, #5aa2c9 61%, #29abe0 100%);
  color: var(--on-donate-accent);
}
.donate-option {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  padding: 0 8px;
  color: inherit;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
  transition: filter 0.15s;
}
.donate-option:hover,
.donate-option:focus-visible { filter: brightness(1.08); }
.donate-option:focus-visible { outline: 2px solid rgba(255,255,255,0.75); outline-offset: -3px; }
.sidebar {
  top: 64px;
  height: calc(100vh - 64px);
  padding: 20px 16px;
  background: var(--bg-primary);
}
.main {
  margin-left: 260px;
  max-width: calc(100vw - 260px);
}
.sidebar-search-wrap { margin: 0 0 18px; }
.sidebar-search {
  background: var(--bg-card);
  border-color: var(--border);
}
.nav-section {
  margin: 18px 8px 8px;
  color: var(--text-muted);
  letter-spacing: 0.1em;
}
.nav-item {
  width: 100%;
  min-height: 36px;
  border: 0;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 13px;
}
.nav-item:hover {
  background: var(--bg-card);
  color: var(--text-primary);
}
.nav-item.active,
.nav-item.is-active {
  background: var(--bg-card);
  color: var(--text-primary);
  border: 0;
  font-weight: 600;
}
.nav-item.active .nav-item-icon,
.nav-item.is-active .nav-item-icon {
  color: var(--accent);
}
.nav-item-count,
.nav-item .count,
.nav-item .nav-count {
  border: 1px solid var(--border);
  background: var(--bg-card);
  border-radius: 999px;
  color: var(--text-muted);
}
.sidebar-add-marker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-secondary);
  cursor: pointer;
}
.sidebar-add-marker:hover {
  color: var(--text-primary);
  border-color: var(--accent);
}
.tweaks-overlay {
  position: fixed;
  inset: 0;
  z-index: 850;
  display: none;
  overflow: hidden;
  background: rgba(0,0,0,0.22);
}
.tweaks-overlay.show { display: block; }
.tweaks-panel {
  position: absolute;
  top: 76px;
  right: 16px;
  display: flex;
  flex-direction: column;
  width: min(380px, calc(100vw - 24px));
  max-height: calc(100vh - 92px);
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg-secondary);
  box-shadow: var(--shadow-lg);
}
.tweaks-head {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg-secondary) 92%, var(--bg-card));
}
.tweaks-head .modal-close {
  position: static;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-muted);
  font-size: 22px;
}
.tweaks-body {
  flex: 1 1 auto;
  min-height: 0;
  max-height: calc(100vh - 172px);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 16px 20px 20px;
}
.tweaks-section {
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.tweaks-section:first-child { padding-top: 0; }
.tweaks-section:last-child { border-bottom: 0; padding-bottom: 0; }
.tweaks-section-title {
  margin-bottom: 10px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.tweaks-theme-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}
.tweaks-theme-btn,
.tweaks-action-grid button {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  width: 100%;
  padding: 9px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
  text-align: left;
}
.tweaks-theme-btn:hover,
.tweaks-action-grid button:hover {
  border-color: var(--accent);
  background: var(--bg-hover);
}
.tweaks-theme-btn.active,
.tweaks-accent-btn.active {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent-fill);
}
.tweaks-accent-row {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
}
.tweaks-option-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.tweaks-option-row .settings-copy {
  min-width: 0;
  flex: 1 1 auto;
}
.tweaks-option-row .settings-copy-title,
.tweaks-option-row .settings-copy-desc {
  overflow-wrap: anywhere;
}
.tweaks-option-row[hidden] {
  display: none;
}
.tweaks-option-row + .tweaks-option-row {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--border);
}
.tweaks-panel.sunset-active .tweaks-accent-row {
  opacity: 0.58;
}
.tweaks-accent-btn {
  height: 38px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-card);
  cursor: pointer;
  padding: 4px;
}
.tweaks-accent-swatch {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 5px;
  background: var(--tweak-gradient, var(--tweak-accent));
}
.tweaks-action-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
@media (max-width: 1024px) {
  .sidebar {
    top: 0;
    height: 100vh;
    padding: 18px 16px;
  }
  .main {
    margin-left: 0;
    max-width: 100%;
  }
}
@media (max-width: 768px) {
  .header {
    min-height: 58px;
    padding: 0 12px;
  }
  .brand { min-width: auto; }
  .header-data-group,
  .feedback-btn,
  .donate-btn {
    display: none !important;
  }
  .header-mid {
    flex: 0 1 auto;
    margin-left: auto;
    justify-content: flex-end;
  }
  .header-right {
    min-width: auto;
    gap: 6px;
  }
  .tweaks-overlay.show { display: flex; }
  .tweaks-overlay {
    align-items: center;
    justify-content: center;
    padding: calc(12px + env(safe-area-inset-top)) calc(12px + env(safe-area-inset-right)) calc(12px + env(safe-area-inset-bottom)) calc(12px + env(safe-area-inset-left));
    box-sizing: border-box;
    background: rgba(0, 0, 0, 0.68);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
  }
  .tweaks-panel {
    position: relative;
    top: auto;
    right: auto;
    left: auto;
    width: min(100%, 380px);
    min-width: 0;
    max-width: 100%;
    height: calc(100vh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
    max-height: calc(100vh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
    box-sizing: border-box;
    box-shadow: 0 12px 24px -20px rgba(0, 0, 0, 0.75);
  }
  .tweaks-body { max-height: none; }
  @supports (height: 100dvh) {
    .tweaks-panel {
      height: calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
      max-height: calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
    }
  }
}
@media (max-width: 480px) {
  .brand-mark,
  .header h1.brand-mark {
    font-size: 17px;
  }
  .profile-compact-btn {
    background: transparent;
  }
  .tweaks-action-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 340px) {
  .brand-mark,
  .header h1.brand-mark {
    display: none;
  }
}

/* Redesign catch-up: sidebar icon sizing and nav count typography glue. */
.sidebar-search-icon,
.nav-item-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 16px;
  width: 16px;
  height: 16px;
  line-height: 1;
}
.sidebar-search-icon svg,
.nav-item-icon svg {
  display: block;
  width: 15px;
  height: 15px;
  stroke: currentColor;
}
.nav-item-icon {
  color: var(--text-muted);
}
.nav-item:hover .nav-item-icon {
  color: var(--text-primary);
}
.nav-item.active .nav-item-icon,
.nav-item.is-active .nav-item-icon {
  color: var(--accent);
}
.nav-item[data-category="dashboard"] .nav-item-dot {
  background: var(--accent);
}
.nav-item-count,
.nav-item .count,
.nav-item .flag-count,
.nav-item .nav-count {
  flex: 0 0 auto;
  max-width: 86px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.nav-item-dot {
  flex: 0 0 8px;
}
.sidebar-add-marker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  float: none;
}

@media (max-width: 768px), (pointer: coarse) {
  .logo-link {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
  }
  .header-share-btn {
    display: none;
  }
  .profile-compact-btn {
    min-width: 44px;
    min-height: 44px;
    justify-content: center;
    padding: 8px;
  }
  .dashboard-widget-tool,
  .lens-widget-dashboard-toggle {
    min-width: 44px;
    min-height: 44px;
    height: auto;
    padding: 0 12px;
    line-height: 1.25;
  }
  .lens-widget-dashboard-toggle {
    padding-inline: 14px;
  }
  .analytics-consent-btn {
    min-width: 44px;
    min-height: 44px;
    padding: 8px 12px;
  }
}

/* Settings modal and settings-owned controls */

.settings-modal .settings-tab-panel {
  min-width: 0;
  padding-top: 0;
  overflow-x: clip;
}
.settings-modal .settings-row {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.settings-modal .settings-row .settings-section {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, auto);
  gap: 16px;
  align-items: center;
  margin: 0;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.settings-modal .settings-row .settings-section > :only-child {
  grid-column: 1 / -1;
}
.settings-modal .settings-section {
  margin-top: 14px;
}
.settings-modal .settings-label {
  margin: 0;
  color: var(--text-primary);
  font-size: 14px;
}
.settings-modal .settings-group-title {
  margin-top: 22px;
  border: 0;
  padding-bottom: 0;
  font-family: var(--font-mono);
  letter-spacing: 0.1em;
}
.settings-modal .local-ai-settings {
  background: var(--bg-card);
  border-color: var(--border);
}
.settings-modal .settings-links-row {
  padding-top: 8px;
  border-top: 1px solid var(--border);
}
.settings-modal .settings-action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}
.settings-modal .settings-action-row + .settings-action-row {
  margin-top: 14px;
}
.settings-modal .settings-copy {
  min-width: 0;
  flex: 1 1 auto;
}
.settings-modal .settings-copy-title {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.35;
}
.settings-modal .settings-copy-desc {
  margin-top: 2px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}
.settings-modal .settings-divider {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px dashed var(--border);
}
.settings-modal .settings-token-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}
.settings-modal .settings-token-actions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}
.settings-modal .settings-token-box {
  min-height: 20px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  line-height: 1.6;
  word-break: break-all;
  user-select: none;
}
.settings-modal .settings-select {
  min-width: 90px;
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--select-surface);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}
.settings-modal .settings-beta-badge {
  display: inline-block;
  margin-left: 5px;
  padding: 2px 5px;
  border: 1px solid var(--border);
  border-radius: 5px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 9px;
  letter-spacing: .06em;
}
.settings-modal .settings-mini-btn {
  padding: 3px 10px;
  font-size: 11px;
  white-space: nowrap;
}
.settings-modal .settings-full-btn {
  width: 100%;
  margin-top: 12px;
  padding: 7px 14px;
  font-size: 12px;
  white-space: nowrap;
}
.settings-modal .api-key-input {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  min-height: 40px;
}
.settings-modal .api-key-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-fill);
}
.settings-modal select.api-key-input {
  appearance: auto;
  -webkit-appearance: menulist;
  cursor: pointer;
  padding-right: 12px;
  background-color: var(--select-surface);
}
.settings-modal select.api-key-input option {
  background: var(--select-popup-surface);
  color: var(--text-primary);
}
@supports (appearance: base-select) {
  .settings-modal select.api-key-input,
  .settings-modal select.api-key-input::picker(select) {
    appearance: base-select;
  }
  .settings-modal select.api-key-input::picker(select) {
    max-height: min(360px, 60vh);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--select-popup-surface);
    color: var(--text-primary);
    box-shadow: var(--shadow-lg);
  }
  .settings-modal select.api-key-input::picker-icon {
    color: var(--text-muted);
  }
  .settings-modal select.api-key-input option {
    padding: 8px 12px;
  }
}

/* API key and provider settings */
.api-key-input {
  width: 100%; padding: 10px 12px; border-radius: 6px;
  border: 1px solid var(--border); background: var(--bg-primary);
  color: var(--text-primary); font-size: 13px; font-family: monospace;
  margin-top: 8px; color-scheme: dark;
}
[data-theme="light"] .api-key-input { color-scheme: light; }
.api-key-input:focus { border-color: var(--accent); }
.api-key-status { font-size: 13px; margin-bottom: 4px; }
.api-key-notice {
  font-size: 11px; color: var(--text-muted); margin-top: 12px;
  padding: 10px; background: var(--bg-card); border-radius: var(--radius-sm);
  border: 1px solid var(--border); line-height: 1.5;
}
.ai-provider-panel { margin-top: 12px; }
.ai-provider-desc {
  font-size: 12px; color: var(--text-muted); line-height: 1.5; margin-bottom: 10px;
}
.ai-model-tip {
  font-size: 12px; line-height: 1.5; color: var(--text-secondary);
  border-left: 3px solid var(--accent); padding: 8px 12px; margin-bottom: 12px;
  background: var(--bg-hover); border-radius: 0 4px 4px 0;
}
/* Local AI settings in Settings modal */
.local-ai-settings { margin-top: 4px; }
.local-ai-status {
  display: flex; align-items: center; gap: 8px; font-size: 13px;
}
.local-ai-status-dot {
  width: 8px; height: 8px; border-radius: 50%; background: var(--text-muted);
  flex-shrink: 0;
}
.local-ai-status-dot.connected { background: var(--green); box-shadow: 0 0 6px rgba(34,197,94,0.5); }
.local-ai-status-dot.disconnected { background: var(--red); }

/* Settings sections */
.settings-section { margin-top: 16px; }
.settings-label { font-size: 13px; font-weight: 600; display: block; margin-bottom: 8px; color: var(--text-secondary); }
.settings-group-title {
  font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--text-muted); margin-top: 24px; padding-bottom: 6px;
  border-bottom: 1px solid var(--border);
}

/* Settings tabs */

.settings-tab-panel { display: none; padding-top: 6px; }
.settings-tab-panel.active {
  display: block;
  animation: settingsTabFadeIn 0.2s ease;
}
@keyframes settingsTabFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
.settings-tab-panel .settings-section:first-child { margin-top: 8px; }
.settings-tab-panel .settings-group-title:first-child { margin-top: 12px; }
.settings-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.settings-row .settings-section { margin-top: 8px; }
.settings-links-row { display: flex; flex-wrap: wrap; gap: 8px 16px; margin-top: 8px; }
.settings-link-btn {
  background: none; border: none; color: var(--text-muted); font-size: 13px;
  font-family: inherit; cursor: pointer; padding: 4px 0; text-decoration: none;
  transition: color 0.15s;
}
.settings-link-btn:hover { color: var(--text-primary); text-decoration: underline; }

/* Theme picker */
.settings-theme-toggle { display: flex; align-items: center; gap: 4px; }
.settings-theme-btn {
  padding: 4px 12px; border-radius: 6px; border: 1px solid var(--border);
  background: transparent; color: var(--text-secondary); font-size: 12px;
  cursor: pointer; font-weight: 500; transition: all 0.15s; font-family: inherit;
}
.settings-theme-btn.active { background: var(--accent); color: white; border-color: var(--accent); }
.settings-theme-btn:hover:not(.active) { background: var(--bg-hover); }
.settings-theme-swatch {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,0.06);
}
.settings-theme-swatch-dark { background: linear-gradient(135deg, #222635 0%, #4f8cff 100%); }
.settings-theme-swatch-light { background: linear-gradient(135deg, #f5f6fa 0%, #3b7cf5 100%); }
.settings-theme-swatch-cyberterm { background: linear-gradient(135deg, #0b0d0b 0%, #4ade80 100%); border-radius: 0; }
.settings-theme-swatch-glass { background: linear-gradient(135deg, #c986ff 0%, #6ec4ff 100%); border-radius: 12px; }
.settings-theme-swatch-synth-sunrise { background: linear-gradient(135deg, #ff7a18 0%, #ff2bd6 50%, #7c3aed 100%); border-radius: 2px; }
.settings-theme-swatch-neuromancer { background: linear-gradient(135deg, #00e5ff 0%, #ff2bd6 100%); border-radius: 0; }

@media (max-width: 720px) {

  .settings-modal .settings-row .settings-section {
    grid-template-columns: 1fr;
    gap: 8px;
    padding: 12px 0;
  }
  .settings-modal .settings-section {
    margin-top: 12px;
  }
  .settings-modal .settings-group-title {
    margin-top: 18px;
  }
  .settings-modal .settings-action-row {
    align-items: flex-start;
    gap: 12px;
  }
  .settings-modal .settings-action-row > .toggle-switch {
    margin-top: 2px;
  }
  .settings-modal .unit-toggle,
  .settings-modal .range-toggle {
    flex-wrap: wrap;
  }
  .settings-modal .range-toggle {
    width: 100%;
  }
  .settings-modal .range-toggle-btn {
    flex: 1 1 0;
    min-width: 0;
  }
  .import-reference-benchmark { align-items: stretch; flex-direction: column; }
  .import-reference-benchmark-actions { flex-basis: auto; width: 100%; }
  .import-reference-benchmark .import-btn { width: 100%; }
}

@media (max-width: 600px) {

}

@media (max-width: 500px) {

  .settings-row { grid-template-columns: 1fr; }
}
